const out = [];
const microtasks = [];
const timers = [];
let now = 0;
let seq = 0;

function parse(piece) {
  const t = piece.trim().split(/\s+/);
  if (t[0] === 'macro') return { kind: 'macro', delay: Number(t[1]), label: t[2] };
  return { kind: t[0], label: t[1] };
}

function run(step, next) {
  out.push(step.label);
  if (next) schedule(next, null);
}

function schedule(step, next) {
  if (step.kind === 'sync') run(step, next);
  else if (step.kind === 'micro') microtasks.push({ step, next });
  else timers.push({ time: now + step.delay, seq: seq++, step, next });
}

function drain() {
  while (microtasks.length) {
    const m = microtasks.shift();
    run(m.step, m.next);
  }
}

for (const line of stdin.split('\n')) {
  if (!line.trim()) continue;
  const pieces = line.split(' then ').map(parse);
  schedule(pieces[0], pieces[1] || null);
}
drain();
while (timers.length) {
  timers.sort((a, b) => a.time - b.time || a.seq - b.seq);
  const t = timers.shift();
  now = t.time;
  run(t.step, t.next);
  drain();
}
console.log(out.join('\n'));

